mapper.sql:
where tenant_id = #{tenantId}

  and status = #{status}


  and priority = #{priority}


  and (
    lower(id) like concat('%', lower(#{keyword}), '%')
    or lower(title) like concat('%', lower(#{keyword}), '%')
    or lower(description) like concat('%', lower(#{keyword}), '%')
  )


  and created_at >= #{startDate}


  and created_at <= #{endDate}

mapper.select:
select count(1)
from biz_ticket
where tenant_id = #{tenantId}

select id, tenant_id, title, description, status, priority, assignee, creator, due_date, created_at, updated_at
from biz_ticket
where tenant_id = #{tenantId}
  and id = #{ticketId}
limit 1

select ticket_id, asset_id from biz_ticket_asset_rel where ticket_id in
#{ticketId}
order by ticket_id asc, asset_id asc
